        s = s.replace('tr', '')
        if ',' in s and '.' not in s:
            s = s.replace(',', '.')
        s = s.replace(',', '')
    elif s.endswith('k'):
        mult = 1000.0
        s = s[:-1]
    s = s.replace(',', '')
    s = re.sub('[^0-9.\\-]', '', s)
    if s in ('', '-', '.'):
        return np.nan
    try:
